#!/usr/bin/env bash
set -Eeuo pipefail
p="${UURB_SOURCE_BUILD_ROOT:?set source build root}"
v="$p/static-variant"
cmake -S "$p/FreeRDP" -B "$v/freerdp-build" -G Ninja \
 "-DCMAKE_USER_MAKE_RULES_OVERRIDE=$UURB_BUILD_RECIPE_DIR/lto-cap.cmake" \
 -DCMAKE_BUILD_TYPE=Release -DCMAKE_INTERPROCEDURAL_OPTIMIZATION=ON -DCMAKE_EXPORT_COMPILE_COMMANDS=ON -DCMAKE_SYSTEM_NAME=Windows -DCMAKE_SYSTEM_PROCESSOR=x86_64 \
 -DCMAKE_C_COMPILER=/usr/bin/x86_64-w64-mingw32-gcc-posix \
 -DCMAKE_CXX_COMPILER=/usr/bin/x86_64-w64-mingw32-g++-posix \
 -DCMAKE_RC_COMPILER=/usr/bin/x86_64-w64-mingw32-windres -DCMAKE_CXX_COMPILER_AR=/usr/bin/x86_64-w64-mingw32-gcc-ar-posix -DCMAKE_CXX_COMPILER_RANLIB=/usr/bin/x86_64-w64-mingw32-gcc-ranlib-posix \
 '-DCMAKE_C_FLAGS=-D__STDC_NO_THREADS__=1' \
 '-DCMAKE_EXE_LINKER_FLAGS=-static-libgcc -static-libstdc++ -Wl,--no-insert-timestamp' \
 '-DCMAKE_SHARED_LINKER_FLAGS=-static-libgcc -static-libstdc++ -Wl,--no-insert-timestamp' \
 "-DCMAKE_FIND_ROOT_PATH=/usr/x86_64-w64-mingw32;$p/runtime/mingw64;$p/codec;$v/install" \
 "-DCMAKE_PREFIX_PATH=$p/runtime/mingw64;$p/codec;$v/install" \
 -DOPENSSL_ROOT_DIR="$p/runtime/mingw64" \
 -DCMAKE_FIND_ROOT_PATH_MODE_PROGRAM=NEVER -DCMAKE_FIND_ROOT_PATH_MODE_LIBRARY=ONLY \
 -DCMAKE_FIND_ROOT_PATH_MODE_INCLUDE=ONLY -DCMAKE_FIND_ROOT_PATH_MODE_PACKAGE=ONLY \
 -DUSE_UNWIND=OFF -DWITH_VERBOSE_WINPR_ASSERT=OFF \
 -DWITH_INTERNAL_MD4=ON -DWITH_INTERNAL_MD5=ON -DWITH_INTERNAL_RC4=ON -DWITH_NATIVE_SSPI=OFF \
 -DWITH_WINPR_TOOLS=OFF -DWITH_CLIENT=ON -DWITH_CLIENT_SDL=ON -DWITH_CLIENT_SDL2=OFF -DWITH_CLIENT_SDL3=ON -DWITH_CLIENT_X11=OFF \
 -DWITH_OPAQUE_SETTINGS=OFF -DWITH_SDL_LINK_SHARED=OFF -DWITH_SDL_IMAGE_DIALOGS=OFF -DWITH_SERVER=OFF -DWITH_CHANNELS=ON \
 -DCHANNEL_URBDRC=OFF -DWITH_PROXY=OFF -DWITH_SHADOW=OFF -DWITH_SAMPLE=ON -DWITH_MANPAGES=OFF \
 -DWITH_OPENH264=ON -DWITH_OPENH264_LOADING=OFF -DOPENH264_INCLUDE_DIR="$p/codec/include" -DOPENH264_LIBRARY="$p/codec/lib/libopenh264.a" \
 -DWITH_FFMPEG=OFF -DWITH_VIDEO_FFMPEG=OFF -DWITH_FFMPEG_HWACCEL=OFF -DWITH_MEDIA_FOUNDATION=OFF -DWITH_SWSCALE=OFF \
 -DWITH_CAIRO=OFF -DWITH_JPEG=OFF -DWITH_KRB5=OFF -DWITH_PKCS11=OFF \
 -DWITH_SMARTCARD_EMULATE=OFF -DWITH_SMARTCARD_INSPECT=OFF -DWITH_FUSE=OFF \
 -DWITH_OPUS=OFF -DWITH_SOXR=OFF -DWITH_YUV=OFF -DWITH_WEBVIEW=OFF -DWITH_FDK_AAC=OFF \
 '-DCMAKE_C_STANDARD_LIBRARIES=-lkernel32 -luser32 -lgdi32 -lwinspool -lshell32 -lole32 -loleaut32 -luuid -lcomdlg32 -ladvapi32 -lstdc++ -lwinpthread' -DSDL3_DIR="$v/install/lib/cmake/SDL3" -DSDL3_ttf_DIR="$v/install/lib/cmake/SDL3_ttf" -DCMAKE_INSTALL_PREFIX=/usr/src/uu-remote/freerdp
python3 "$UURB_BUILD_RECIPE_DIR/check-lto.py" "$v/freerdp-build" require-ipo
ninja -C "$v/freerdp-build" -j 2 sdl3-freerdp
